/**
 * Populate the column, looks through the column object and populates
 * The associated div
 * @param {object} e
 * @param {string} t
 */
function populate_col(e, t) {
  const o = document.getElementById(t),
    n = document.createElement("h1");
  ((n.textContent = e.name), o.appendChild(n));
  for (const t in e.items)
    if ("object" == typeof e.items[t]) {
      const n = document.createElement("div");
      n.className = "dropdown-wrapper";
      var i = document.createElement("p");
      i.textContent = t;
      var l = document.createElement("ul");
      l.className = "submenu";
      for (const o in e.items[t]) {
        var c = document.createElement("li"),
          m = document.createElement("a");
        ((m.href = e.items[t][o]),
          (m.textContent = o),
          c.appendChild(m),
          l.appendChild(c));
      }
      (i.appendChild(l), n.appendChild(i), o.appendChild(n));
    } else {
      var a = document.createElement("p"),
        s = document.createElement("a");
      (console.log(e.items[t]),
        (s.href = e.items[t]),
        (s.textContent = t),
        a.appendChild(s),
        o.appendChild(a));
    }
}

function setupWelcomeMessage() {
  let e = new Date().getHours();
  ((e = Math.floor(e / 6)), 4 == e && (e = 3));
  let t = "Good " + WELCOME_MESSAGE_TEMPLATE[e] + ", " + NAME;
  document.getElementById("welcome-string").innerHTML = t;
}

function main() {
  populate_col(col1, "col1");
  populate_col(col2, "col2");
  populate_col(col3, "col3");
  populate_col(col4, "col4");
  setupWelcomeMessage();
}
main();
